import {booking} from "../common/request.mjs";
import {renew} from "../common/renewals.mjs";

/** Apply Studio's allocation without changing the shared ledger's default policy. */
function reserveStudio(ledger, request, catalog) {
  // Existing IDs must keep the journal's replay/conflict/cancellation semantics,
  // even when the tenant is now at (or above) its allocation.
  if (ledger.inspect(request.id)) return ledger.reserve(request);

  const cap = catalog.studios.get(request.tenant) ?? catalog.default;
  const used = ledger.usage(request.tenant, request.day);
  if (used + request.units > cap) {
    return {status: "full", id: request.id, remaining: Math.max(0, cap - used)};
  }
  ledger.post(request);
  return {status: "booked", id: request.id, remaining: cap - used - request.units};
}

export function bookStudio(ledger, input, catalog) {
  return reserveStudio(ledger, booking(input), catalog);
}

export function renewStudio(ledger, operation, catalog) {
  // Reuse renewal validation and inheritance, replacing only admission policy.
  return renew({
    inspect: id => ledger.inspect(id),
    reserve: request => reserveStudio(ledger, request, catalog)
  }, operation);
}
