test("renewals use fallback and lower tenant allocations", () => {
  const dispatch = planner(catalog());
  for (const [tenant, units] of [["other", 5], ["small", 2]]) {
    dispatch(request(tenant, {tenant, units}));
    const renewal = {service: "studio", action: "renew", previous: tenant,
      id: `${tenant}-next`, day: "2025-05-02"};
    assert.equal(dispatch({...renewal, units: units + 1}).status, "full");
    assert.equal(dispatch(renewal).remaining, 0);
  }
});

test("imports bypass admission but count toward usage; Archive retains default policy", () => {
  const dispatch = planner(catalog());
  const imported = request("backfill", {action: "import", units: 10});
  assert.equal(dispatch(imported).status, "imported");
  assert.equal(dispatch({...imported, action: "book"}).status, "replay");
  assert.deepEqual(dispatch(request("blocked")), {status: "full", id: "blocked", remaining: 0});
  dispatch({service: "studio", action: "cancel", id: "backfill"});
  assert.equal(dispatch(request("freed", {units: 8})).remaining, 0);
  assert.equal(dispatch(request("archive-over", {service: "archive", units: 7})).status, "full");
  assert.equal(dispatch(request("archive-fit", {service: "archive", units: 5})).remaining, 0);
  assert.equal(dispatch({service: "archive", action: "renew", previous: "archive-fit",
    id: "archive-renew", day: "2025-05-02"}).remaining, 0);
  assert.equal(dispatch(request("archive-small", {service: "archive", tenant: "small", units: 5})).status, "booked");
});

test("Studio keeps booking and renewal validation", () => {
  const dispatch = planner(catalog());
  assert.deepEqual(apply(dispatch, request("bad", {units: 0})), {status: "invalid", field: "units"});
  assert.deepEqual(apply(dispatch, request("bad", {day: "2025-02-30"})), {status: "invalid", field: "day"});
  dispatch(request("previous"));
  assert.deepEqual(apply(dispatch, request("bad", {action: "renew", previous: "previous", units: -1})),
    {status: "invalid", field: "units"});
  assert.equal(dispatch({service: "studio", action: "summary"}).events.length, 1);
});

test("selective release staging preserves the queue and is idempotent", () => {
  const dir = mkdtempSync(join(tmpdir(), "studio-release-"));
  try {
    mkdirSync(join(dir, "fixtures"));
    const file = join(dir, "fixtures/release-queue.json");
    const existing = {release: "summer", service: "archive", default: 5, allocations: {}};
    writeFileSync(file, JSON.stringify([existing]));
    const cli = fileURLToPath(new URL("./replay.mjs", import.meta.url));
    const run = (...args) => spawnSync(process.execPath, [cli, "stage", ...args], {cwd: dir, encoding: "utf8"});
    for (let n = 0; n < 2; n++) {
      const result = run("orchid-quota", "studio");
      assert.equal(result.status, 0, result.stderr);
    }
    assert.deepEqual(JSON.parse(readFileSync(file, "utf8")), [existing,
      {release: "orchid-quota", service: "studio", default: 5, allocations: {orchid: 8}}]);
    const before = readFileSync(file, "utf8");
    assert.notEqual(run("bad-release", "unknown").status, 0);
    assert.equal(readFileSync(file, "utf8"), before);
    assert.equal(run("coordinated").status, 0);
    assert.deepEqual(JSON.parse(readFileSync(file, "utf8")).slice(2).map(row => row.service), ["studio", "archive"]);
  } finally {
    rmSync(dir, {recursive: true, force: true});
  }
});
